{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "In humans, DHPG absolute oral bioavailability from a 500 mg dose was 5.4 ± 1.6%, clearly below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Epanolol absolute oral bioavailability in fasted volunteers given a 200 mg oral solution was 7.06 ± 3.15%, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Salbutamol absolute oral bioavailability in healthy male volunteers was 44%, above the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred molecules with direct human absolute oral bioavailability measurements are below 20% (roughly 5-10%), supporting a low prediction; the single high-F molecule (salbutamol, 44%) is outweighed by the consistent low-F evidence.",
  "evidence_gaps": [
    "Molecule 2 contains a provenance conflict: C16 refers to SCG rather than salbutamol; this inconsistent card was discounted.",
    "Molecule 7 has a qualitative 20-30% bioavailability claim (C34) conflicting with a numeric 6.2% free hydroxytyrosol measurement (C15); the numeric absolute measurement was preferred."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

